solution.solution.cpp:
#include <algorithm>
#include <cmath>
#include <cstdint>
#include <map>
#include <optional>
#include <vector>

struct Entity
{
    std::uint16_t id;
    std::uint16_t x;
    std::uint16_t y;
    std::uint8_t angle;
    std::uint8_t health;
};

std::uint16_t quantize(float value, float min, float max)
{
    if (std::isnan(value)) return 0;
    const double t{ (std::clamp(static_cast<double>(value), static_cast<double>(min), static_cast<double>(max)) - min) / (static_cast<double>(max) - min) };
    return static_cast<std::uint16_t>(std::lround(t * 65535.0));
}

float dequantize(std::uint16_t q, float min, float max)
{
    return static_cast<float>(min + (static_cast<double>(max) - min) * q / 65535.0);
}

namespace
{
    void put16(std::vector<std::uint8_t>& b, std::uint16_t v)
    {
        b.push_back(static_cast<std::uint8_t>(v >> 8));
        b.push_back(static_cast<std::uint8_t>(v));
    }

    void writeEntry(std::vector<std::uint8_t>& out, const Entity& e, std::uint8_t mask)
    {
        put16(out, e.id);
        out.push_back(mask);
        if (mask & 0x01) put16(out, e.x);
        if (mask & 0x02) put16(out, e.y);
        if (mask & 0x04) out.push_back(e.angle);
        if (mask & 0x08) out.push_back(e.health);
    }
}

std::vector<std::uint8_t> encodeDelta(const std::vector<Entity>& baseline, const std::vector<Entity>& current)
{
    std::vector<std::uint8_t> out{ 0, 0 };
    std::uint16_t entries{ 0 };
    std::size_t i{ 0 }, j{ 0 };
    while (i < baseline.size() || j < current.size())
    {
        if (j == current.size() || (i < baseline.size() && baseline[i].id < current[j].id))
        {
            writeEntry(out, baseline[i++], 0x80);
            ++entries;
        }
        else if (i == baseline.size() || current[j].id < baseline[i].id)
        {
            writeEntry(out, current[j++], 0x0F);
            ++entries;
        }
        else
        {
            const Entity& a{ baseline[i++] };
            const Entity& b{ current[j++] };
            std::uint8_t mask{ 0 };
            if (a.x != b.x) mask |= 0x01;
            if (a.y != b.y) mask |= 0x02;
            if (a.angle != b.angle) mask |= 0x04;
            if (a.health != b.health) mask |= 0x08;
            if (mask == 0) continue;
            writeEntry(out, b, mask);
            ++entries;
        }
    }
    out[0] = static_cast<std::uint8_t>(entries >> 8);
    out[1] = static_cast<std::uint8_t>(entries);
    return out;
}

std::optional<std::vector<Entity>> decodeDelta(const std::vector<Entity>& baseline, const std::vector<std::uint8_t>& d)
{
    std::map<std::uint16_t, Entity> world;
    for (const Entity& e : baseline) world[e.id] = e;
    std::size_t at{ 0 };
    const auto need{ [&](std::size_t n) { return d.size() - at >= n; } };
    const auto take16{ [&] { const auto v{ static_cast<std::uint16_t>((d[at] << 8) | d[at + 1]) }; at += 2; return v; } };

    if (!need(2)) return std::nullopt;
    const std::uint16_t entries{ take16() };
    std::optional<std::uint16_t> previous;
    for (std::uint16_t n{ 0 }; n < entries; ++n)
    {
        if (!need(3)) return std::nullopt;
        const std::uint16_t id{ take16() };
        const std::uint8_t mask{ d[at++] };
        if (previous && id <= *previous) return std::nullopt;
        previous = id;
        const auto found{ world.find(id) };
        if (mask == 0x80)
        {
            if (found == world.end()) return std::nullopt;
            world.erase(found);
            continue;
        }
        if (mask == 0 || (mask & 0xF0) != 0) return std::nullopt;
        if (found == world.end() && mask != 0x0F) return std::nullopt;
        Entity e{ found == world.end() ? Entity{ id, 0, 0, 0, 0 } : found->second };
        if (mask & 0x01) { if (!need(2)) return std::nullopt; e.x = take16(); }
        if (mask & 0x02) { if (!need(2)) return std::nullopt; e.y = take16(); }
        if (mask & 0x04) { if (!need(1)) return std::nullopt; e.angle = d[at++]; }
        if (mask & 0x08) { if (!need(1)) return std::nullopt; e.health = d[at++]; }
        world[id] = e;
    }
    if (at != d.size()) return std::nullopt;
    std::vector<Entity> out;
    for (const auto& [id, e] : world) out.push_back(e);
    return out;
}

unitTests:
using Bytes = std::vector<std::uint8_t>;
bool same(const std::vector<Entity>& a, const std::vector<Entity>& b) {
    if (a.size() != b.size()) return false;
    for (std::size_t i{ 0 }; i < a.size(); ++i)
        if (a[i].id != b[i].id || a[i].x != b[i].x || a[i].y != b[i].y || a[i].angle != b[i].angle || a[i].health != b[i].health) return false;
    return true;
}
TEST("quantising") {
    CHECK_EQ(quantize(0, 0, 1000), 0);
    CHECK_EQ(quantize(1000, 0, 1000), 65535);
    CHECK_EQ(quantize(500, 0, 1000), 32768);
    CHECK_EQ(quantize(-5, 0, 1000), 0);
    CHECK_EQ(quantize(2000, 0, 1000), 65535);
    CHECK_EQ(quantize(0, -100, 100), 32768);
    CHECK_EQ(quantize(std::nanf(""), 0, 1000), 0);
    CHECK_NEAR(dequantize(65535, 0, 1000), 1000, 1e-3);
    CHECK_NEAR(dequantize(0, -100, 100), -100, 1e-4);
    for (float v : { 0.0f, 1.234f, 333.3f, 500.0f, 999.99f })
        CHECK_NEAR(dequantize(quantize(v, 0, 1000), 0, 1000), v, 1000.0 / 65535 / 2 + 1e-3);
}
TEST("encoding only what changed") {
    const std::vector<Entity> base{ { 1, 100, 200, 10, 100 }, { 2, 300, 400, 20, 50 } };
    const std::vector<Entity> next{ { 1, 101, 200, 10, 100 }, { 2, 300, 400, 20, 50 } };
    CHECK(encodeDelta(base, next) == (Bytes{ 0, 1, 0, 1, 0x01, 0, 101 }));
    CHECK(encodeDelta(base, base) == (Bytes{ 0, 0 }));
    const std::vector<Entity> hurt{ { 1, 100, 200, 10, 100 }, { 2, 300, 401, 20, 45 } };
    CHECK(encodeDelta(base, hurt) == (Bytes{ 0, 1, 0, 2, 0x0A, 0x01, 0x91, 45 }));
}
TEST("new and removed entities") {
    const std::vector<Entity> base{ { 1, 100, 200, 10, 100 }, { 5, 1, 2, 3, 4 } };
    const std::vector<Entity> next{ { 3, 0x1234, 0x5678, 9, 8 }, { 5, 1, 2, 3, 4 } };
    CHECK(encodeDelta(base, next) == (Bytes{ 0, 2, 0, 1, 0x80, 0, 3, 0x0F, 0x12, 0x34, 0x56, 0x78, 9, 8 }));
    CHECK(encodeDelta({}, { { 7, 1, 1, 1, 1 } }) == (Bytes{ 0, 1, 0, 7, 0x0F, 0, 1, 0, 1, 1, 1 }));
}
TEST("decoding round trips") {
    const std::vector<Entity> base{ { 1, 100, 200, 10, 100 }, { 2, 300, 400, 20, 50 }, { 9, 9, 9, 9, 9 } };
    const std::vector<Entity> next{ { 2, 300, 999, 21, 50 }, { 4, 1, 2, 3, 4 }, { 9, 9, 9, 9, 9 }, { 12, 5, 5, 5, 5 } };
    const auto decoded{ decodeDelta(base, encodeDelta(base, next)) };
    CHECK(decoded.has_value() && same(*decoded, next));
    const auto unchanged{ decodeDelta(base, Bytes{ 0, 0 }) };
    CHECK(unchanged.has_value() && same(*unchanged, base));
    const auto fromNothing{ decodeDelta({}, encodeDelta({}, next)) };
    CHECK(fromNothing.has_value() && same(*fromNothing, next));
}
TEST("rejecting bad deltas") {
    const std::vector<Entity> base{ { 1, 100, 200, 10, 100 }, { 2, 300, 400, 20, 50 } };
    CHECK(!decodeDelta(base, Bytes{ 0 }).has_value());
    CHECK(!decodeDelta(base, Bytes{ 0, 1, 0, 1, 0x01, 0 }).has_value());
    CHECK(!decodeDelta(base, Bytes{ 0, 0, 7 }).has_value());
    CHECK(!decodeDelta(base, Bytes{ 0, 2, 0, 2, 0x08, 1, 0, 1, 0x08, 2 }).has_value());
    CHECK(!decodeDelta(base, Bytes{ 0, 1, 0, 1, 0x00 }).has_value());
    CHECK(!decodeDelta(base, Bytes{ 0, 1, 0, 1, 0x10 }).has_value());
    CHECK(!decodeDelta(base, Bytes{ 0, 1, 0, 1, 0x81 }).has_value());
    CHECK(!decodeDelta(base, Bytes{ 0, 1, 0, 3, 0x80 }).has_value());
    CHECK(!decodeDelta(base, Bytes{ 0, 1, 0, 3, 0x01, 0, 5 }).has_value());
    CHECK(!decodeDelta(base, Bytes{ 0, 2, 0, 1, 0x08, 1 }).has_value());
}

